<template><div class="workflow-page"><header class="page-head"><div><span class="eyebrow">收购 / 质检端</span><h1>质量检验</h1><p>记录称重、等级、含水率和复检状态。</p></div><button class="primary" @click="showForm=!showForm">{{showForm?'收起':'新建质检'}}</button></header><form v-if="showForm" class="form-panel" @submit.prevent="create"><div class="form-grid"><label>收购批次号<input v-model="form.purchase_no" placeholder="如 2026-Q-001" required></label><label>采收批次<select v-model="form.harvest_batch_id" required><option value="">请选择</option><option v-for="b in harvests" :value="b.id" :key="b.id">{{b.batch_no}} · {{b.fresh_weight}} kg</option></select></label><label>称重（kg）<input v-model="form.weight" type="number" step="0.01" min="0" required></label><label>等级<input v-model="form.grade" placeholder="如 C3F"></label><label>含水率（%）<input v-model="form.moisture" type="number" step="0.1" min="0" max="100"></label><label>状态<select v-model="form.status"><option value="pending">待质检</option><option value="passed">已通过</option><option value="recheck">需复检</option></select></label></div><label>外观与备注<textarea v-model="form.notes" rows="3"></textarea></label><button class="primary" :disabled="busy">{{busy?'保存中...':'保存质检'}}</button><p v-if="message" class="message">{{message}}</p></form><section class="table-panel"><div class="panel-title"><strong>质检记录</strong><span>{{items.length}} 条</span></div><div v-if="!items.length" class="empty">暂无质检记录，不显示虚构等级或价格。</div><div v-for="item in items" :key="item.id" class="batch-row"><div><strong>{{item.purchase_no}}</strong><small>{{item.grade||'未定级'}} · {{item.weight}} kg · 含水率 {{item.moisture||'—'}}%</small></div><span class="status">{{statusText[item.status]||item.status}}</span></div></section></div></template>
<script>
import axios from 'axios'; import {API_BASE} from '@/config/api';
export default{data:()=>({harvests:[],items:[],showForm:false,busy:false,message:'',statusText:{pending:'待质检',passed:'已通过',recheck:'需复检'},form:{purchase_no:'',harvest_batch_id:'',weight:'',grade:'',moisture:'',status:'pending',notes:''}}),async mounted(){await Promise.all([this.loadHarvests(),this.load()]);},methods:{async loadHarvests(){const r=await axios.get(`${API_BASE}/harvest/batches/`);this.harvests=r.data.data?.items||[];},async load(){const r=await axios.get(`${API_BASE}/quality/inspections/`);this.items=r.data.data?.items||[];},async create(){this.busy=true;try{await axios.post(`${API_BASE}/quality/inspections/`,this.form);this.message='质检记录已保存';this.showForm=false;await this.load();}catch(e){this.message=e.response?.data?.msg||'保存失败';}finally{this.busy=false;}}}};
</script>
<style scoped>.workflow-page{max-width:1060px;margin:auto}.page-head{display:flex;justify-content:space-between;padding:18px 2px}.eyebrow{font-size:12px;color:#27865a;font-weight:700}.page-head h1{margin:6px 0;color:#1b583c;font-size:26px}.page-head p{margin:0;color:#789081;font-size:13px}.primary{border:0;background:#1f8758;color:#fff;border-radius:7px;padding:10px 15px}.form-panel,.table-panel{background:#fff;border:1px solid #dcebe1;border-radius:12px;padding:17px;margin-bottom:14px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}label{display:block;color:#41634f;font-size:12px;font-weight:600;margin-bottom:13px}input,select,textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:10px;border:1px solid #cfe2d5;border-radius:7px;font:inherit;font-weight:400}.panel-title{display:flex;justify-content:space-between;color:#285f43}.panel-title span,.batch-row small{color:#81988a;font-size:12px}.empty{text-align:center;padding:35px 5px;color:#82998d;font-size:13px}.batch-row{display:flex;justify-content:space-between;border-top:1px solid #edf3ee;padding:13px 0}.batch-row small{display:block;margin-top:4px}.status{padding:4px 8px;border-radius:20px;background:#e8f5ed;color:#278258;font-size:12px}.message{color:#2b8258;font-size:13px}@media(max-width:650px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:430px){.form-grid{grid-template-columns:1fr}}</style>
